  const arc=deg===90?`<path d="M${c[0]+18} ${c[1]}v-18h-18" class="thin"/>`:`<path d="M${c[0]+30} ${c[1]}A30 30 0 ${deg>180?1:0} 0 ${rd(c[0]+30*Math.cos(a),1)} ${rd(c[1]-30*Math.sin(a),1)}" class="thin"/>`;
