const setMean=(m,n)=>{let v;do{v=list(n-1,m-8,m+8);v.push(n*m-v.reduce((a,b)=>a+b));}while(v[n-1]<1||v[n-1]>m+12||v[n-1]<m-12);return shuffle(v);};
