/* ENTRY LEVEL 1 - follows the Growing Futures annual session plan (blocks 1 to 5; block 6 is consolidation). */
level('e1',{name:'Entry Level 1',short:'E1',blocks:[
 {n:1,title:'Numbers to 20',aim:'Count, recognise and compare quantities and numbers to 20.'},
 {n:2,title:'Adding and subtracting',aim:'Add and subtract within 20 using appropriate methods.'},
 {n:3,title:'Money, clocks and calendars',aim:'Recognise money and use familiar time information.'},
 {n:4,title:'Comparing, shapes and position',aim:'Compare everyday objects and describe shape and position.'},
 {n:5,title:'Lists, sorting and simple charts',aim:'Read and represent simple information.'},
 {n:6,title:'Consolidation and exam preparation',aim:'Apply the full Entry Level 1 curriculum independently in familiar tasks.'}]});
const twoBars=(a,b,vert)=>{const k=9;return svg(vert?150:230,vert?200:96,vert?`<rect x="30" y="${190-a*k}" width="30" height="${a*k}" class="bar"/><rect x="92" y="${190-b*k}" width="30" height="${b*k}" class="bar"/>`+T(45,12,'A',{b:1})+T(107,12,'B',{b:1}):`<rect x="30" y="10" width="${a*k}" height="26" class="bar"/><rect x="30" y="56" width="${b*k}" height="26" class="bar"/>`+T(14,28,'A',{b:1})+T(14,74,'B',{b:1}),`Two ${vert?'posts':'planks'}, A and B`,1.1);};
const shapeRow=names=>`<div class="shrow">${names.map(n=>figShape(n)).join('')}</div>`;

topic('e1-count',{b:1,s:1,title:'Counting to 20',area:'N',dfe:'2',vq:'counting objects to 20',
 lesson:{idea:'Counting tells you how many things there are. Say one number for each thing. The last number you say is how many.',steps:['Touch or point to each thing once as you count.','Count in order: 1, 2, 3 and so on.','If there is nothing there, the number is zero. We write 0.'],ex:{q:'A tray has two rows of five pots. How many pots?',w:['Count the top row: 1, 2, 3, 4, 5.','Carry on along the next row: 6, 7, 8, 9, 10.','There are 10 pots.']},trap:'Do not count the same thing twice. Go along one row at a time.'},
 gens:[()=>{const n=rnd(1,20);return{text:'How many dots are there?',fig:figItems(n),ans:n,steps:['Count along each row, one number for each dot.',`There are <b>${n}</b>.`]};},
  ()=>{const n=rnd(3,20);return{text:'Count the squares. How many are there?',fig:figItems(n,5,true),...mcn(n,[n-1,n+1,n+2,n-2]),steps:['Each full row has 5 squares.',`Count them all: <b>${n}</b>.`]};},
  ()=>{const zero=rnd(1,3)===1,n=zero?0:rnd(1,6),th=pick(THINGS);return{text:`A box is for ${th}. Each dot is one. How many are in the box?`,fig:zero?svg(140,60,'<rect x="6" y="6" width="128" height="48" rx="6" class="tray"/>','An empty box'):figItems(n),ans:n,steps:[zero?'The box is empty. Nothing is there.':'Count each dot once.',`The answer is <b>${n}</b>${zero?'. We call this zero.':'.'}`]};}]});

topic('e1-read',{b:1,s:2,title:'Reading numbers to 20',area:'N',dfe:'1',vq:'reading numbers to 20',
 lesson:{idea:'Every number can be written as a figure, like 14, or as a word, like fourteen. You need to know both.',steps:['Learn the words for 0 to 10 first.','The "teen" numbers are 13 to 19. Fourteen is 14, sixteen is 16.','Twenty is 20.'],ex:{q:'A sign says "twelve seats". What number is that?',w:['Twelve comes after eleven.','Ten is 10, eleven is 11, twelve is 12.','It is 12.']},trap:'12 and 20 can look alike in a hurry. Twelve is 12. Twenty is 20.'},
 gens:[()=>{const n=rnd(0,20);return{text:`Which number is <b>${n===0?'zero':words(n)}</b>?`,...mcn(n,[n+1,n-1,n+10,n-10,rnd(0,20)]),steps:[`Say it out loud: ${n===0?'zero':words(n)}.`,`As a figure it is <b>${n}</b>.`]};},
  ()=>{const n=rnd(1,20),W=k=>cap(words(k));return{text:`How do you say this number?<br><span class="bigno">${n}</span>`,...mcn(n,[n+1,n-1,n+2,n-2,n+10,n-10].filter(x=>x>0&&x<=20),W),steps:[`The number ${n} is said <b>${words(n)}</b>.`]};}]});

topic('e1-write',{b:1,s:3,title:'Writing numbers to 20',area:'N',dfe:'1',vq:'writing numbers to 20',
 lesson:{idea:'When you count things, write the total as a figure so other people can read it.',steps:['Numbers 0 to 9 use one digit.','Numbers 10 to 20 use two digits. The 1 at the front means one ten.','Sixteen is 1 ten and 6 ones, so write 16.'],ex:{q:'Write the number thirteen in figures.',w:['Thirteen is 1 ten and 3 ones.','Write the 1 first, then the 3.','13']},trap:'Write the ten first. Thirteen is 13, not 31.'},
 gens:[()=>{const n=rnd(0,20);return{text:`Write the number <b>${n===0?'zero':words(n)}</b> in figures.`,ans:n,steps:[`${cap(n===0?'zero':words(n))} is written <b>${n}</b>.`]};},
  ()=>{const n=rnd(11,20),th=pick(THINGS);return{text:`A stock list says "${words(n)} ${th}". Write the number in figures.`,ans:n,steps:[`${cap(words(n))} is 1 ten and ${n-10} ones.`,`Write <b>${n}</b>.`]};}]});

topic('e1-order',{b:1,s:4,title:'Putting numbers in order',area:'N',dfe:'1',vq:'ordering numbers to 20 number line',
 lesson:{idea:'Numbers go in order, like houses on a street. A number line shows the order from smallest to biggest.',steps:['Start at the smallest number.','Each step to the right is one more.','To find a missing number, count on from the number before it.'],ex:{q:'What number is missing? 7, 8, __, 10',w:['Count on from 7: 7, 8, 9, 10.','The missing number is 9.']},trap:'Check the order by counting out loud. 12 comes before 13, not after it.'},
 gens:[()=>{const lo=rnd(0,12),m=lo+rnd(1,7);return{text:'What number is missing from the number line?',fig:figNumLine(lo,lo+8,1,{hide:[m]}),ans:m,steps:[`Count along from ${lo}.`,`The missing number is <b>${m}</b>.`]};},
  ()=>{const n=rnd(1,19),aft=rnd(0,1)===1;return{text:`What number comes just ${aft?'after':'before'} ${n}?`,ans:aft?n+1:n-1,steps:[aft?`One more than ${n} is <b>${n+1}</b>.`:`One less than ${n} is <b>${n-1}</b>.`]};},
  ()=>{const v=pickN([...Array(21).keys()],4),asc=v.slice().sort((a,b)=>a-b),right=asc.join(', '),wr=new Set();while(wr.size<3){const s=shuffle(v).join(', ');if(s!==right)wr.add(s);}
   return{text:'Which list is in order, smallest first?',...mc(right,[...wr]),steps:[`The smallest is ${asc[0]}. The biggest is ${asc[3]}.`,`In order: <b>${right}</b>`]};}]});

topic('e1-compare',{b:1,s:5,title:'More, fewer and equal',area:'N',dfe:'1',vq:'comparing numbers more fewer',
 lesson:{idea:'Comparing means deciding which is more and which is fewer. If two amounts are the same, they are equal.',steps:['Count each group.','The bigger number is more. The smaller number is fewer.','On a number line, the number further right is bigger.'],ex:{q:'Tray A has 8 pots. Tray B has 11 pots. Which has more?',w:['8 comes before 11 when you count.','So 11 is the bigger number.','Tray B has more.']},trap:'A group that is spread out can look bigger. Always count.'},
 gens:[()=>{let a=rnd(1,20),b;do{b=rnd(1,20);}while(b===a);const big=rnd(0,1)===1;return{text:`Which number is ${big?'bigger':'smaller'}?`,...mc(String(big?Math.max(a,b):Math.min(a,b)),[String(big?Math.min(a,b):Math.max(a,b))]),steps:[`When you count, ${Math.min(a,b)} comes before ${Math.max(a,b)}.`,`The ${big?'bigger':'smaller'} number is <b>${big?Math.max(a,b):Math.min(a,b)}</b>.`]};},
  ()=>{const a=rnd(3,12),b=rnd(1,3)===1?a:rnd(3,12),more=rnd(0,1)===1,o=['Tray A','Tray B','They are the same'];return{text:`Which tray has ${more?'more':'fewer'} dots?`,fig:`<p class="cap">Tray A</p>${figItems(a)}<p class="cap">Tray B</p>${figItems(b)}`,kind:'choice',opts:o,ans:a===b?2:(more?(a>b?0:1):(a<b?0:1)),steps:[`Tray A has ${a}. Tray B has ${b}.`,a===b?'<b>They are the same</b>. We say they are equal.':`<b>${more?(a>b?'Tray A':'Tray B'):(a<b?'Tray A':'Tray B')}</b> has ${more?'more':'fewer'}.`]};}]});

topic('e1-add',{b:2,s:7,title:'Adding up to 20',area:'N',dfe:'3',vq:'addition within 20',
 lesson:{idea:'Adding means putting groups together to find how many there are altogether.',steps:['Start with the bigger number.','Count on the smaller number. Use fingers, objects or a number line.','The number you land on is the total.'],ex:{q:'8 + 5',w:['Start at 8.','Count on 5: 9, 10, 11, 12, 13.','8 + 5 = 13']},trap:'When you count on, do not count the number you start on.'},
 gens:[()=>{const a=rnd(1,15),b=rnd(1,20-a);return{text:`Work out <span class="fm">${a} + ${b}</span>`,ans:a+b,steps:[`Start at ${Math.max(a,b)} and count on ${Math.min(a,b)}.`,`${a} + ${b} = <b>${a+b}</b>`]};},
  ()=>{const a=rnd(2,10),b=rnd(1,10),th=pick(THINGS);return{text:`There are ${a} ${th} in one box and ${b} in another box. How many are there altogether?`,fig:`<p class="cap">Box 1</p>${figItems(a)}<p class="cap">Box 2</p>${figItems(b)}`,ans:a+b,steps:['Altogether means add.',`${a} + ${b} = <b>${a+b}</b>`]};}]});

topic('e1-sub',{b:2,s:8,title:'Taking away within 20',area:'N',dfe:'3',vq:'subtraction within 20',
 lesson:{idea:'Subtracting means taking some away and finding how many are left.',steps:['Start at the first number.','Count back the number you are taking away.','The number you land on is what is left.'],ex:{q:'14 − 3',w:['Start at 14.','Count back 3: 13, 12, 11.','14 − 3 = 11']},trap:'Always start from the bigger number. You are taking away from it.'},
 gens:[()=>{const a=rnd(3,20),b=rnd(1,a);return{text:`Work out <span class="fm">${a} − ${b}</span>`,ans:a-b,steps:[`Start at ${a} and count back ${b}.`,`${a} − ${b} = <b>${a-b}</b>`]};},
  ()=>{const a=rnd(6,20),b=rnd(1,a-1),th=pick(THINGS),n=who();return{text:`There are ${a} ${th} on the shelf. ${n} takes ${b} away. How many are left?`,ans:a-b,steps:['Takes away means subtract.',`${a} − ${b} = <b>${a-b}</b>`]};}]});

topic('e1-sym',{b:2,s:9,title:'The signs +, − and =',area:'N',dfe:'4',vq:'plus minus equals symbols',
 lesson:{idea:'Maths uses signs to save writing. + means add. − means take away. = means "is the same as".',steps:['+ (plus) makes the amount bigger.','− (minus) makes the amount smaller.','= (equals) goes before the answer.'],ex:{q:'Which sign is missing? 6 __ 2 = 8',w:['8 is bigger than 6, so something was added.','6 + 2 = 8','The missing sign is +.']},trap:'Look at whether the answer is bigger or smaller than the first number.'},
 gens:[()=>{const add=rnd(0,1)===1,a=rnd(4,12),b=rnd(1,add?20-a:a-1),r=add?a+b:a-b;return{text:`Which sign is missing?<br><span class="fm">${a} ☐ ${b} = ${r}</span>`,kind:'choice',opts:['+','−','='],ans:add?0:1,steps:[`${r} is ${add?'bigger':'smaller'} than ${a}.`,`So ${b} was ${add?'added':'taken away'}. The sign is <b>${add?'+':'−'}</b>.`]};},
  ()=>{const a=rnd(5,15),b=rnd(1,4),add=rnd(0,1)===1;return{text:`Which sum means "${a} ${add?'add':'take away'} ${b}"?`,...mc(`${a} ${add?'+':'−'} ${b}`,[`${a} ${add?'−':'+'} ${b}`,`${a} = ${b}`]),steps:[`${add?'Add uses the + sign.':'Take away uses the − sign.'}`,`<b>${a} ${add?'+':'−'} ${b}</b>`]};},
  ()=>{const a=rnd(2,9),b=rnd(1,9);return{text:`Which sign is missing?<br><span class="fm">${a} + ${b} ☐ ${a+b}</span>`,kind:'choice',opts:['+','−','='],ans:2,steps:[`${a} + ${b} is the same as ${a+b}.`,'"Is the same as" is the equals sign: <b>=</b>']};}]});

topic('e1-choose',{b:2,s:10,title:'Add or take away?',area:'N',dfe:'3, 4',vq:'addition subtraction word problems',
 lesson:{idea:'In real life nobody tells you which sum to do. Look for clue words in the question.',steps:['Words like "altogether", "more" and "in total" mean add.','Words like "left", "take away", "gives away" and "fewer" mean subtract.','Do the sum, then check your answer makes sense.'],ex:{q:'There are 12 eggs. 4 are used. How many are left?',w:['"Left" means take away.','12 − 4 = 8','8 eggs are left.']},trap:'Read the whole question first. Do not just add the two numbers you see.'},
 gens:[()=>{const add=rnd(0,1)===1,a=rnd(6,14),b=rnd(1,5),th=pick(THINGS);return{text:add?`There are ${a} ${th}. ${b} more arrive. Do you add or take away to find how many there are now?`:`There are ${a} ${th}. ${b} are given away. Do you add or take away to find how many are left?`,kind:'choice',opts:['Add','Take away'],ans:add?0:1,steps:[add?'"More arrive" makes the number bigger.':'"Given away" makes the number smaller.',`So you <b>${add?'add':'take away'}</b>: ${a} ${add?'+':'−'} ${b} = ${add?a+b:a-b}`]};},
  ()=>{const add=rnd(0,1)===1,a=rnd(6,14),b=rnd(1,5),n=who(),th=pick(['pencils','stickers','tokens','cards']);return{text:add?`${n} has ${a} ${th} and is given ${b} more. How many does ${n} have now?`:`${n} has ${a} ${th} and gives ${b} away. How many does ${n} have left?`,ans:add?a+b:a-b,steps:[add?'"Given more" means add.':'"Gives away" means take away.',`${a} ${add?'+':'−'} ${b} = <b>${add?a+b:a-b}</b>`]};}]});

topic('e1-coins',{b:3,s:13,title:'Coins and notes',area:'M',dfe:'5',vq:'recognising UK coins and notes',
 lesson:{idea:'UK money comes in coins and notes. Small amounts are in pence (p). Bigger amounts are in pounds (£).',steps:['The coins are 1p, 2p, 5p, 10p, 20p, 50p, £1 and £2.','The notes are £5, £10 and £20.','Write p after pence, like 5p. Write £ before pounds, like £5.'],ex:{q:'How do you write "ten pounds"?',w:['Pounds use the £ sign.','The sign goes first.','£10']},trap:'5p and £5 are very different. One is a small coin. The other is a note.'},
 gens:[()=>{const v=pick([1,2,5,10,20,50,100,200,500,1000,2000]),W=x=>x<100?(x===1?'One penny':cap(words(x))+' pence'):(x===100?'One pound':cap(words(x/100))+' pounds'),n=v<100?v:v/100,wr=[v<100?n*100:n,v<100?(n===1?2:n===2?20:n*2):n*10,v<100?(n>=10?n/10:n*10):(n>=10?n/10*100:n*2*100)].filter(x=>x!==v);return{text:`How much is this ${v>=500?'note':'coin'} worth?`,fig:figMoney([v]),...mc(W(v),[...new Set(wr.map(W))].filter(x=>x!==W(v))),hint:'A p after the number means pence. A £ before the number means pounds.',steps:[`It says ${pence(v)}.`,`That is <b>${W(v).toLowerCase()}</b>.`]};},
  ()=>{const[a,b]=pickN([1,2,5,10,20,50,100,200,500,1000,2000],2),more=rnd(0,1)===1;return{text:`Which is worth ${more?'more':'less'}?`,fig:figMoney([a,b]),...mc(pence(more?Math.max(a,b):Math.min(a,b)),[pence(more?Math.min(a,b):Math.max(a,b))]),steps:['Pounds are worth more than pence. There are 100 pence in £1.',`<b>${pence(more?Math.max(a,b):Math.min(a,b))}</b> is worth ${more?'more':'less'}.`]};},
  ()=>{const n=pick([1,2,5,10,20]),pd=rnd(0,1)===1;return{text:`How do you write "${words(n)} ${pd?(n===1?'pound':'pounds'):(n===1?'penny':'pence')}"?`,...mc(pd?`£${n}`:`${n}p`,pd?[`${n}p`,`${n}£`,`p${n}`]:[`£${n}`,`${n}£`,`p${n}`]),steps:[pd?'Pounds: the £ sign goes in front.':'Pence: the p goes after the number.',`<b>${pd?`£${n}`:`${n}p`}</b>`]};}]});

topic('e1-money',{b:3,s:14,title:'Using money',area:'M',dfe:'5, 3',vq:'adding coins simple money',
 lesson:{idea:'To find how much money you have, add the values of the coins or notes.',steps:['Say what each coin is worth.','Start with the biggest and count on.','Write p for pence or £ for pounds with your answer.'],ex:{q:'You have a 10p, a 5p and a 2p. How much is that?',w:['Start with 10p.','Add 5p: 15p.','Add 2p: 17p.']},trap:'Count what the coins are worth, not how many coins there are.'},
 gens:[()=>{let c,t;do{c=pickN([1,1,2,2,5,5,10],rnd(2,3));t=c.reduce((a,b)=>a+b);}while(t>20);c.sort((a,b)=>b-a);return{text:'How much money is this altogether?',fig:figMoney(c),ans:t,suf:'p',steps:[`Add the values: ${c.join(' + ')}.`,`Total: <b>${t}p</b>`]};},
  ()=>{const price=rnd(3,19),pay=price<=10?pick([10,20]):20;return{text:`A sticker costs ${price}p. You pay with a ${pay}p coin. How much change do you get?`,ans:pay-price,suf:'p',steps:['Change is what you paid take away the price.',`${pay} − ${price} = <b>${pay-price}p</b>`]};},
  ()=>{const c=pickN([5,5,10],2),t=c[0]+c[1];return{text:'How much money is this altogether?',fig:figMoney(c.map(x=>x*100)),ans:t,pre:'£',steps:[`£${c[0]} + £${c[1]}`,`= <b>£${t}</b>`]};}]});

const oclock=h=>`${h} o'clock`;
topic('e1-aclock',{b:3,s:15,title:"Clocks with hands: o'clock",area:'M',dfe:'6',vq:"telling the time o'clock analogue",
 lesson:{idea:'A clock with hands has a short hand and a long hand. The short hand shows the hour.',steps:['Find the long hand. If it points straight up to 12, it is an o\'clock time.','Now find the short hand. The number it points to is the hour.','Say the number, then "o\'clock".'],ex:{q:'The long hand points to 12. The short hand points to 4. What time is it?',w:['Long hand on 12 means o\'clock.','Short hand on 4 means the hour is 4.','It is 4 o\'clock.']},trap:'Do not mix up the hands. The short hand tells you the hour.'},
 gens:[()=>{const h=rnd(1,12);return{text:'What time does the clock show?',fig:figClock(h,0),...mcn(h,[h%12+1,(h+10)%12+1,12,(h+5)%12+1],oclock),steps:['The long hand points to 12, so it is an o\'clock time.',`The short hand points to ${h}. It is <b>${h} o'clock</b>.`]};},
  ()=>{const h=rnd(1,11),act=pick(['The bus leaves','Lunch starts','The session ends','The shop opens']);return{text:`${act} at the time on the clock. Where is the short hand pointing?`,fig:figClock(h,0),ans:h,steps:['The short hand is the hour hand.',`It points to <b>${h}</b>, so the time is ${h} o'clock.`]};}]});

topic('e1-dclock',{b:3,s:16,title:"Digital clocks: o'clock",area:'M',dfe:'6',vq:"digital clock o'clock times",
 lesson:{idea:'A digital clock shows the time in numbers. The number before the dots is the hour.',steps:['Read the number before the two dots. That is the hour.','If the numbers after the dots are 00, it is an o\'clock time.','7:00 is 7 o\'clock.'],ex:{q:'A digital clock shows 9:00. What time is it?',w:['The hour is 9.','00 after the dots means o\'clock.','It is 9 o\'clock.']},trap:'A clock showing 7:00 is a time, not the number seven hundred.'},
 gens:[()=>{const h=rnd(1,12);return{text:'What time does the digital clock show?',fig:figDigital(h+':00'),...mcn(h,[h%12+1,(h+10)%12+1,(h+5)%12+1,(h+2)%12+1],oclock),steps:[`The hour is ${h}. The minutes are 00.`,`It is <b>${h} o'clock</b>.`]};},
  ()=>{const h=rnd(1,12);return{text:'Which digital clock shows the same time as this clock?',fig:figClock(h,0),...mcn(h,[h%12+1,(h+10)%12+1,(h+5)%12+1,(h+2)%12+1],x=>x+':00'),steps:[`The clock with hands shows ${h} o'clock.`,`On a digital clock that is <b>${h}:00</b>.`]};}]});

topic('e1-days',{b:3,s:17,title:'Days of the week',area:'M',dfe:'7',vq:'days of the week order',
 lesson:{idea:'There are 7 days in a week. They always come in the same order.',steps:['Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday.','Saturday and Sunday are the weekend.','After Sunday the week starts again at Monday.'],ex:{q:'Which day comes after Wednesday?',w:['Say the days in order: Monday, Tuesday, Wednesday, Thursday.','Thursday comes after Wednesday.']},trap:'Tuesday and Thursday sound alike. Tuesday is day 2. Thursday is day 4.'},
 gens:[()=>{const i=rnd(0,6),aft=rnd(0,1)===1,a=DAYS[(i+(aft?1:6))%7];return{text:`Which day comes just ${aft?'after':'before'} ${DAYS[i]}?`,...mct(a,DAYS.filter(d=>d!==DAYS[i])),steps:['Say the days in order.',`<b>${a}</b> comes ${aft?'after':'before'} ${DAYS[i]}.`]};},
  ()=>{const m=rnd(0,2);return m===0?{text:'How many days are there in a week?',ans:7,steps:['Count them: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday.','There are <b>7</b>.']}:m===1?{text:'Which of these days is at the weekend?',...mc(pick(['Saturday','Sunday']),['Monday','Wednesday','Friday']),steps:['The weekend is Saturday and Sunday.']}:{text:'If Monday is day 1 of the week, which day is day 3?',...mc('Wednesday',['Tuesday','Thursday','Friday']),steps:['Day 1 Monday, day 2 Tuesday, day 3 <b>Wednesday</b>.']};},
  ()=>{const acts=pickN(['Woodwork','Cooking','Climbing','Gardening','Maths'],5),i=rnd(0,4);return{text:`Look at the timetable. Which day is ${acts[i].toLowerCase()}?${tbl(['Day','Activity'],DAYS.slice(0,5).map((d,k)=>[d,acts[k]]))}`,...mct(DAYS[i],DAYS.slice(0,5)),steps:[`Find ${acts[i]} in the list.`,`Read across to the day: <b>${DAYS[i]}</b>.`]};}]});

const SEASON=m=>['Winter','Winter','Spring','Spring','Spring','Summer','Summer','Summer','Autumn','Autumn','Autumn','Winter'][m];
topic('e1-months',{b:3,s:18,title:'Months and seasons',area:'M',dfe:'7',vq:'months of the year and seasons',
 lesson:{idea:'There are 12 months in a year and 4 seasons. They always come in the same order.',steps:['January, February, March, April, May, June, July, August, September, October, November, December.','The seasons are spring, summer, autumn and winter.','In the UK, July is in summer and January is in winter.'],ex:{q:'Which month comes after May?',w:['Say the months in order: April, May, June.','June comes after May.']},trap:'June and July are easy to mix up. June is month 6. July is month 7.'},
 gens:[()=>{const i=rnd(0,11),aft=rnd(0,1)===1,a=MONTHS[(i+(aft?1:11))%12];return{text:`Which month comes just ${aft?'after':'before'} ${MONTHS[i]}?`,...mct(a,MONTHS.filter(d=>d!==MONTHS[i])),steps:['Say the months in order.',`<b>${a}</b> comes ${aft?'after':'before'} ${MONTHS[i]}.`]};},
  ()=>{const m=rnd(0,2);return m===0?{text:'How many months are there in a year?',ans:12,steps:['Count them from January to December.','There are <b>12</b>.']}:m===1?{text:'How many seasons are there in a year?',ans:4,steps:['Spring, summer, autumn, winter.','There are <b>4</b>.']}:(()=>{const k=rnd(1,12);return{text:`Which month is month number ${k} of the year?`,...mct(MONTHS[k-1],MONTHS),steps:['Count from January, which is month 1.',`Month ${k} is <b>${MONTHS[k-1]}</b>.`]};})();},
  ()=>{const i=pick([0,3,6,9,7,1]);return{text:`In the UK, which season is ${MONTHS[i]} in?`,...mct(SEASON(i),['Spring','Summer','Autumn','Winter']),steps:['Winter: December to February. Spring: March to May. Summer: June to August. Autumn: September to November.',`${MONTHS[i]} is in <b>${SEASON(i).toLowerCase()}</b>.`]};}]});

topic('e1-size',{b:4,s:19,title:'Size, length and height',area:'M',dfe:'8',vq:'comparing length and height longer shorter',
 lesson:{idea:'We compare things with words like bigger and smaller, longer and shorter, taller and shorter, wider and narrower.',steps:['Line the two things up at one end.','See which one goes further. That one is longer or taller.','Use the right word: length is longer or shorter. Height is taller or shorter.'],ex:{q:'A rope is 5 metres. A hose is 9 metres. Which is longer?',w:['9 is more than 5.','The hose is longer.']},trap:'Make sure both things start at the same place before you compare.'},
 gens:[()=>{let a=rnd(6,20),b;do{b=rnd(6,20);}while(Math.abs(a-b)<3);const lg=rnd(0,1)===1;return{text:`Which plank is ${lg?'longer':'shorter'}?`,fig:twoBars(a,b),kind:'choice',opts:['Plank A','Plank B'],ans:(lg?a>b:a<b)?0:1,steps:['Both planks start at the same place.',`Plank <b>${(lg?a>b:a<b)?'A':'B'}</b> is ${lg?'longer':'shorter'}.`]};},
  ()=>{let a=rnd(6,19),b;do{b=rnd(6,19);}while(Math.abs(a-b)<3);const tl=rnd(0,1)===1;return{text:`Which post is ${tl?'taller':'shorter'}?`,fig:twoBars(a,b,true),kind:'choice',opts:['Post A','Post B'],ans:(tl?a>b:a<b)?0:1,steps:['Both posts stand on the same ground.',`Post <b>${(tl?a>b:a<b)?'A':'B'}</b> is ${tl?'taller':'shorter'}.`]};},
  ()=>{const[x,y,w1,w2]=pick([['a bus','a car','longer','shorter'],['a door','a window sill','taller','shorter'],['a motorway','a footpath','wider','narrower'],['a house','a shed','bigger','smaller'],['a ladder','a chair','taller','shorter']]),f=rnd(0,1)===1;return{text:`Which word fits? ${cap(f?x:y)} is usually ____ than ${f?y:x}.`,...mc(f?w1:w2,[f?w2:w1]),steps:[`Picture the two things side by side.`,`${cap(f?x:y)} is <b>${f?w1:w2}</b>.`]};}]});

topic('e1-weight',{b:4,s:20,title:'Weight and capacity',area:'M',dfe:'8',vq:'heavier lighter full empty capacity',
 lesson:{idea:'Weight is how heavy something is. Capacity is how much a container holds.',steps:['Heavier things are harder to lift. Lighter things are easier.','A bigger container holds more.','A container can be full, half full or empty.'],ex:{q:'Which is heavier: a brick or a sponge?',w:['A brick is hard to lift with one finger. A sponge is easy.','The brick is heavier.']},trap:'Big does not always mean heavy. A big balloon is lighter than a small stone.'},
 gens:[()=>{const[h,l]=pick([['a brick','a feather'],['a full bucket of water','an empty bucket'],['a wheelbarrow','a trowel'],['a bag of sand','a bag of crisps'],['a bike','a helmet'],['a stone','a balloon']]),hv=rnd(0,1)===1;return{text:`Which is ${hv?'heavier':'lighter'}?`,...mc(cap(hv?h:l),[cap(hv?l:h)]),steps:['Think about lifting each one.',`<b>${cap(hv?h:l)}</b> is ${hv?'heavier':'lighter'}.`]};},
  ()=>{const[b,s]=pick([['a bucket','a mug'],['a bath','a sink'],['a watering can','a teaspoon'],['a water butt','a bottle'],['a kettle','an egg cup']]),m=rnd(0,1)===1;return{text:`Which holds ${m?'more':'less'} water?`,...mc(cap(m?b:s),[cap(m?s:b)]),steps:['The bigger container holds more.',`<b>${cap(m?b:s)}</b> holds ${m?'more':'less'}.`]};},
  ()=>{const i=rnd(0,2);return{text:'Look at the jug. How full is it?',fig:figScale({min:0,max:10,major:5,minor:5,val:[9.9,5,0.05][i],unit:'',vert:true,jug:true}).replace(/<text[^>]*>[^<]*<\/text>/g,''),kind:'choice',opts:['Full','Half full','Empty'],ans:i,steps:[['The water reaches the top.','The water reaches the middle.','There is no water in it.'][i],`The jug is <b>${['full','half full','empty'][i]}</b>.`]};}]});

topic('e1-2d',{b:4,s:21,title:'Flat shapes',area:'M',dfe:'9',vq:'2D shapes circle square rectangle triangle',
 lesson:{idea:'Flat shapes are called 2D shapes. You see them on signs, packets and screens.',steps:['A circle is perfectly round.','A triangle has 3 straight sides.','A rectangle has 4 straight sides and 4 square corners. A square is a rectangle with all 4 sides the same.'],ex:{q:'A give-way sign has 3 straight sides. What shape is it?',w:['Count the sides: 3.','A shape with 3 sides is a triangle.']},trap:'A shape is still the same shape if it is turned round or made bigger.'},
 gens:[()=>{const n=pick(['circle','square','rectangle','triangle']);return{text:'What is this shape called?',fig:figShape(n,n==='circle'?0:pick([0,0,20,180])),...mct(cap(n),['Circle','Square','Rectangle','Triangle']),steps:[{circle:'It is round with no corners.',square:'It has 4 equal sides and 4 square corners.',rectangle:'It has 4 sides and 4 square corners. Two sides are longer.',triangle:'It has 3 straight sides.'}[n],`It is a <b>${n}</b>.`]};},
  ()=>{const n=pick(['circle','square','rectangle','triangle']),o=shuffle(['circle','square','rectangle','triangle']);return{text:`Which shape is a ${n}?`,kind:'choice',opts:o.map(x=>figShape(x)),ans:o.indexOf(n),steps:[{circle:'Look for the round shape.',square:'Look for 4 equal sides.',rectangle:'Look for 4 sides with two longer than the others.',triangle:'Look for 3 sides.'}[n],`The ${n}: ${figShape(n)}`]};},
  ()=>{const row=[...Array(rnd(5,7))].map(()=>pick(['circle','square','triangle'])),n=pick(['circle','square','triangle']),c=row.filter(x=>x===n).length;return{text:`How many ${n}s are there?`,fig:shapeRow(row),ans:c,steps:[`Point to each ${n} and count.`,`There ${c===1?'is':'are'} <b>${c}</b>.`]};}]});

topic('e1-3d',{b:4,s:22,title:'Solid shapes',area:'M',dfe:'9',vq:'3D shapes cube cylinder sphere',
 lesson:{idea:'Solid shapes are called 3D shapes. You can pick them up. Boxes, tins and balls are all 3D shapes.',steps:['A cube is a box where every face is a square. A dice is a cube.','A cylinder is a tube shape. A tin of beans is a cylinder.','A sphere is a ball shape.'],ex:{q:'What shape is a dice?',w:['Every face of a dice is a square.','A dice is a cube.']},trap:'A square is flat. A cube is solid. A drawing of a cube shows more than one face.'},
 gens:[()=>{const n=pick(['cube','cylinder','sphere','cuboid']);return{text:'What is this solid shape called?',fig:figShape(n),...mct(cap(n),['Cube','Cylinder','Sphere','Cuboid']),steps:[{cube:'Every face is a square.',cylinder:'It has two round ends, like a tin.',sphere:'It is round like a ball.',cuboid:'It is a box with rectangle faces.'}[n],`It is a <b>${n}</b>.`]};},
  ()=>{const[n,ob]=pick([['cube','A dice'],['sphere','A football'],['cylinder','A tin of beans'],['cuboid','A cereal box']]);return{text:`Which of these is the shape of a ${n}?`,...mct(ob,['A dice','A football','A tin of beans','A cereal box']),steps:[`${ob} is a <b>${n}</b> shape.`]};},
  ()=>{const flat=rnd(0,1)===1,n=flat?pick(['circle','square','triangle','rectangle']):pick(['cube','cylinder','sphere','cuboid']);return{text:'Is this shape flat (2D) or solid (3D)?',fig:figShape(n),kind:'choice',opts:['Flat (2D)','Solid (3D)'],ans:flat?0:1,steps:[flat?`A ${n} is flat. You could draw it on paper.`:`A ${n} is solid. You could pick it up.`,`It is <b>${flat?'flat (2D)':'solid (3D)'}</b>.`]};}]});

topic('e1-pos',{b:4,s:23,title:'Position and direction',area:'M',dfe:'10',vq:'position words left right above below',
 lesson:{idea:'Position words say where something is: left, right, in front, behind, under and above.',steps:['Left and right are the two sides. On this screen, left is the side where you start reading.','Above means higher up. Under means lower down.','In a queue, the person in front of you is closer to the start.'],ex:{q:'The cup is above the plate. Which one is higher up?',w:['Above means higher.','The cup is higher up.']},trap:'Check left and right with your hands. Your left hand makes an L shape with finger and thumb.'},
 gens:[()=>{const n=pickN(['Mug','Box','Ball','Hat','Key'],3),l=rnd(0,1)===1;return{text:`What is on the ${l?'left':'right'} of the ${n[1].toLowerCase()}?`,fig:figCards(n),...mc(n[l?0:2],[n[l?2:0],n[1]]),steps:[`Find the ${n[1].toLowerCase()} in the middle.`,`On its ${l?'left':'right'} is the <b>${n[l?0:2].toLowerCase()}</b>.`]};},
  ()=>{const n=pickN(['Paint','Nails','Rope','Glue','Tape'],3),ab=rnd(0,1)===1;return{text:`These are three shelves. What is ${ab?'above':'under'} the ${n[1].toLowerCase()}?`,fig:figCards(n,true),...mc(n[ab?0:2],[n[ab?2:0],n[1]]),steps:[`Find the ${n[1].toLowerCase()} on the middle shelf.`,`${ab?'Above':'Under'} it is the <b>${n[ab?0:2].toLowerCase()}</b>.`]};},
  ()=>{const n=pickN(NAMES,3),fr=rnd(0,1)===1;return{text:`Three people are in a queue. Who is ${fr?'in front of':'behind'} ${n[1]}?`,fig:figCards(n,false,'← Front of the queue'),...mc(n[fr?0:2],[n[fr?2:0],n[1]]),steps:['The front of the queue is on the left.',`<b>${n[fr?0:2]}</b> is ${fr?'in front of':'behind'} ${n[1]}.`]};}]});

const stock=()=>{const it=pickN(THINGS,4),v=pickN([...Array(19).keys()].map(x=>x+2),4);return{it,v};};
topic('e1-lists',{b:5,s:25,title:'Reading lists',area:'D',dfe:'11',vq:'reading information from a list',
 lesson:{idea:'A list shows information in rows. Each row has a name and a number that goes with it.',steps:['Find the name you need in the list.','Read across the same row to find its number.','Check you have not slipped onto the row above or below.'],ex:{q:'A list says: Helmets 12, Ropes 7. How many ropes?',w:['Find "Ropes".','Read across: 7.','There are 7 ropes.']},trap:'Use your finger or a ruler to stay on the right row.'},
 gens:[()=>{const{it,v}=stock(),i=rnd(0,3);return{text:`Look at the stock list. How many ${it[i]} are there?${tbl(['Item','Number'],it.map((x,k)=>[cap(x),v[k]]))}`,ans:v[i],steps:[`Find ${cap(it[i])} in the list.`,`Read across: <b>${v[i]}</b>.`]};},
  ()=>{const{it,v}=stock(),mx=rnd(0,1)===1,t=mx?Math.max(...v):Math.min(...v),i=v.indexOf(t);return{text:`Look at the stock list. Which item is there the ${mx?'most':'fewest'} of?${tbl(['Item','Number'],it.map((x,k)=>[cap(x),v[k]]))}`,...mc(cap(it[i]),it.filter((_,k)=>k!==i).map(cap)),steps:[`Look for the ${mx?'biggest':'smallest'} number: ${t}.`,`That is <b>${cap(it[i])}</b>.`]};}]});

topic('e1-sort',{b:5,s:26,title:'Sorting',area:'D',dfe:'12',vq:'sorting objects into groups',
 lesson:{idea:'Sorting means putting things that are alike into the same group. You choose one rule, like colour, shape or type.',steps:['Decide the rule, for example "tools" or "fruit".','Look at each thing. Does it fit the rule?','Count how many are in the group.'],ex:{q:'Apple, hammer, pear, saw. How many are fruit?',w:['Apple: fruit. Hammer: not fruit. Pear: fruit. Saw: not fruit.','2 are fruit.']},trap:'Check every item against the rule, one at a time.'},
 gens:[()=>{const sets={fruit:['apple','banana','pear','orange','plum'],tools:['hammer','saw','spanner','drill','chisel'],clothes:['coat','hat','glove','boot','scarf']},ks=pickN(Object.keys(sets),2),a=rnd(1,4),b=rnd(2,4),list=shuffle([...pickN(sets[ks[0]],a),...pickN(sets[ks[1]],b)]);return{text:`Look at this list:<br><b>${list.join(', ')}</b><br>How many are ${ks[0]}?`,ans:a,steps:[`The ${ks[0]}: ${list.filter(x=>sets[ks[0]].includes(x)).join(', ')}.`,`That is <b>${a}</b>.`]};},
  ()=>{const sets=[['Fruit',['Apple','Banana','Pear','Orange']],['Tools',['Hammer','Saw','Spanner','Drill']],['Animals',['Dog','Sheep','Horse','Cat']]],[g,o]=pickN(sets,2),three=pickN(g[1],3),odd=pick(o[1]);return{text:'Which one does not belong in the group?',...mc(odd,three),steps:[`${three.join(', ')} are all ${g[0].toLowerCase()}.`,`<b>${odd}</b> is not.`]};},
  ()=>{const row=[...Array(rnd(6,8))].map(()=>pick(['circle','square','triangle'])),n=pick(['circle','square','triangle']),c=row.filter(x=>x===n).length;return{text:`Sort these shapes. How many go in the "${n}s" group?`,fig:shapeRow(row),ans:c,steps:[`Pick out each ${n}.`,`There ${c===1?'is':'are'} <b>${c}</b>.`]};}]});

const tallyData=()=>{const c=pickN(['Tea','Coffee','Juice','Water','Milk','Squash'],4),v=c.map(()=>rnd(1,14));return{c,v};};
topic('e1-tally',{b:5,s:27,title:'Tally charts',area:'D',dfe:'13',vq:'tally charts',
 lesson:{idea:'A tally is a quick way to count. You draw one line for each thing. Every fifth line goes across the other four, like a gate.',steps:['Each bundle with a line across is 5.','Count the bundles in fives: 5, 10, 15.','Then add on the single lines.'],ex:{q:'A tally shows two bundles and 3 single lines. What is the total?',w:['Two bundles: 5, 10.','Add 3 single lines: 11, 12, 13.','The total is 13.']},trap:'The line across is the fifth one. A full bundle is 5, not 4.'},
 gens:[()=>{const n=rnd(1,18);return{text:`What number does this tally show?<br>${tally(n)}`,ans:n,steps:[`Count the bundles in fives: ${Math.floor(n/5)} bundle${Math.floor(n/5)===1?'':'s'} is ${Math.floor(n/5)*5}.`,`Add ${n%5} single lines: <b>${n}</b>.`]};},
  ()=>{const{c,v}=tallyData(),i=rnd(0,3);return{text:`People chose a drink. How many chose ${c[i].toLowerCase()}?${tbl(['Drink','Tally'],c.map((x,k)=>[x,tally(v[k])]))}`,ans:v[i],steps:[`Find ${c[i]} and count its tally in fives.`,`<b>${v[i]}</b> people chose ${c[i].toLowerCase()}.`]};},
  ()=>{const n=rnd(6,14),o=shuffle([n,n-1,n+1,n-5]);return{text:`Which tally shows ${n}?`,kind:'choice',opts:o.map(tally),ans:o.indexOf(n),steps:[`${n} is ${Math.floor(n/5)} bundle${Math.floor(n/5)===1?'':'s'} of five and ${n%5} more.`,tally(n)]};}]});

const blockData=()=>{const c=pickN(['Bus','Car','Walk','Bike','Taxi'],4),v=c.map(()=>rnd(1,8));return{c,v};};
topic('e1-block',{b:5,s:28,title:'Block graphs',area:'D',dfe:'13',vq:'block graphs block diagrams',
 lesson:{idea:'A block graph uses one block for each thing. A taller tower means more.',steps:['Read the name under the tower.','Count the blocks in that tower, or read the number at the side.','To compare, look for the tallest and shortest towers.'],ex:{q:'The "Bus" tower has 6 blocks. The "Car" tower has 4. How many more came by bus?',w:['6 take away 4.','6 − 4 = 2','2 more came by bus.']},trap:'Count the blocks, not the lines between them.'},
 gens:[()=>{const{c,v}=blockData(),i=rnd(0,3);return{text:`The block graph shows how people travel. How many ${pick(['people use','chose'])} "${c[i]}"?`,fig:figBars(c,v,{blocks:true,max:8,xl:'How people travel',yl:'People'}),ans:v[i],steps:[`Find the ${c[i]} tower.`,`Count its blocks: <b>${v[i]}</b>.`]};},
  ()=>{let d;do{d=blockData();}while(d.v.filter(x=>x===Math.max(...d.v)).length>1||d.v.filter(x=>x===Math.min(...d.v)).length>1);const mx=rnd(0,1)===1,i=d.v.indexOf(mx?Math.max(...d.v):Math.min(...d.v));return{text:`Which is the ${mx?'most':'least'} popular way to travel?`,fig:figBars(d.c,d.v,{blocks:true,max:8,xl:'How people travel',yl:'People'}),...mc(d.c[i],d.c.filter((_,k)=>k!==i)),steps:[`Look for the ${mx?'tallest':'shortest'} tower.`,`It is <b>${d.c[i]}</b> with ${d.v[i]}.`]};},
  ()=>{let d,i,j;do{d=blockData();[i,j]=pickN([0,1,2,3],2);}while(d.v[i]<=d.v[j]);return{text:`How many more people chose "${d.c[i]}" than "${d.c[j]}"?`,fig:figBars(d.c,d.v,{blocks:true,max:8,xl:'How people travel',yl:'People'}),ans:d.v[i]-d.v[j],steps:[`${d.c[i]}: ${d.v[i]}. ${d.c[j]}: ${d.v[j]}.`,`${d.v[i]} − ${d.v[j]} = <b>${d.v[i]-d.v[j]}</b>`]};}]});

