/* ENTRY LEVEL 2 - follows the Growing Futures annual session plan. */
level('e2',{name:'Entry Level 2',short:'E2',blocks:[
 {n:1,title:'Whole numbers and calculation',aim:'Read and compare numbers, calculate with two digits and check answers.'},
 {n:2,title:'Multiplication, division, fractions and decimals',aim:'Use multiplication and division facts and recognise simple fractions and decimals.'},
 {n:3,title:'Money, time and metric measures',aim:'Use money, dates, clocks and standard metric units.'},
 {n:4,title:'Scales, temperature, shapes and position',aim:'Read simple scales and describe shapes and positions.'},
 {n:5,title:'Sorting and presenting information',aim:'Extract, compare and represent information using lists, tables and bar charts.'},
 {n:6,title:'Consolidation and exam preparation',aim:'Apply the full Entry Level 2 curriculum independently in familiar tasks.'}]});

topic('e2-count100',{b:1,s:1,title:'Counting to 100',area:'N',dfe:'1',vq:'counting to 100 tens and ones',
 lesson:{idea:'Big groups are quicker to count in tens. Count the full tens first, then add the ones left over.',steps:['Put the things into groups of ten.','Count the tens: 10, 20, 30 and so on.','Then count on the single ones.'],ex:{q:'There are 4 full rows of ten and 6 more. How many?',w:['4 tens: 10, 20, 30, 40.','Count on 6: 46.','There are 46.']},trap:'Check each row really has ten before you count in tens.'},
 gens:[()=>{const n=rnd(21,100);return{text:'Each full row has 10 dots. How many dots are there altogether?',fig:figItems(n,10),ans:n,steps:[`There are ${Math.floor(n/10)} full rows of ten: ${Math.floor(n/10)*10}.`,`Add the ${n%10} left over: <b>${n}</b>.`]};},
  ()=>{const g=rnd(2,9),r=rnd(1,9),th=pick(THINGS);return{text:`There are ${g} bags with 10 ${th} in each bag, and ${r} loose ${r===1?'one':'ones'}. How many ${th} altogether?`,ans:g*10+r,steps:[`${g} tens are ${g*10}.`,`${g*10} + ${r} = <b>${g*10+r}</b>`]};}]});

topic('e2-num200',{b:1,s:2,title:'Numbers to 200',area:'N',dfe:'2',vq:'place value hundreds tens ones numbers to 200',
 lesson:{idea:'In a number like 146, each digit has a job. The 1 is one hundred, the 4 is four tens and the 6 is six ones.',steps:['Read the hundreds first, then the tens, then the ones.','To compare two numbers, look at the hundreds first. If they match, look at the tens, then the ones.','Write numbers in order by starting with the smallest.'],ex:{q:'Which is bigger: 127 or 172?',w:['Both have 1 hundred.','Look at the tens: 2 tens and 7 tens.','172 is bigger.']},trap:'109 is one hundred and nine. It is not the same as 190.'},
 gens:[()=>{const n=rnd(21,200);return{text:`Write this number in figures: <b>${words(n)}</b>.`,ans:n,steps:[`Hundreds: ${Math.floor(n/100)}. Tens: ${Math.floor(n%100/10)}. Ones: ${n%10}.`,`<b>${n}</b>`]};},
  ()=>{const v=pickN([...Array(180).keys()].map(x=>x+20),4),big=rnd(0,1)===1,t=big?Math.max(...v):Math.min(...v);return{text:`Which number is the ${big?'biggest':'smallest'}?`,...mc(String(t),v.filter(x=>x!==t).map(String)),steps:[`In order: ${v.slice().sort((a,b)=>a-b).join(', ')}.`,`The ${big?'biggest':'smallest'} is <b>${t}</b>.`]};},
  ()=>{const n=rnd(111,199),i=rnd(0,2),d=String(n)[i];return{text:`In the number ${n}, what is the ${['hundreds','tens','ones'][i]} digit?`,ans:+d,steps:[`${n} is ${String(n)[0]} hundred, ${String(n)[1]} tens and ${String(n)[2]} ones.`,`The ${['hundreds','tens','ones'][i]} digit is <b>${d}</b>.`]};}]});

topic('e2-oddeven',{b:1,s:3,title:'Odd and even numbers',area:'N',dfe:'3',vq:'odd and even numbers',
 lesson:{idea:'Even numbers can be shared into two equal groups. Odd numbers always have one left over.',steps:['Look at the last digit only.','If it is 0, 2, 4, 6 or 8 the number is even.','If it is 1, 3, 5, 7 or 9 the number is odd.'],ex:{q:'Is 47 odd or even?',w:['The last digit is 7.','7 is odd.','So 47 is odd.']},trap:'Only the last digit matters. 30 is even even though 3 is odd.'},
 gens:[()=>{const n=rnd(1,100);return{text:`Is ${n} odd or even?`,kind:'choice',opts:['Odd','Even'],ans:n%2?0:1,steps:[`The last digit is ${n%10}.`,`${n} is <b>${n%2?'odd':'even'}</b>.`]};},
  ()=>{const s=rnd(1,88),up=rnd(0,2)>0,seq=[0,1,2,3].map(i=>up?s+2*i:s+8-2*i),nx=up?s+8:s;return{text:`What is the next number in this pattern?<br><b>${seq.join(', ')}, __</b>`,ans:nx,steps:[`The numbers go ${up?'up':'down'} in twos. They are all ${s%2?'odd':'even'}.`,`The next number is <b>${nx}</b>.`]};},
  ()=>{const odd=rnd(0,1)===1,r=rnd(5,49)*2+(odd?1:0),w=pickN([...Array(45).keys()].map(x=>(x+3)*2+(odd?0:1)),3);return{text:`Which of these is an ${odd?'odd':'even'} number?`,...mc(String(r),w.map(String)),steps:['Check the last digit of each number.',`<b>${r}</b> ends in ${r%10}, so it is ${odd?'odd':'even'}.`]};}]});

topic('e2-add',{b:1,s:4,title:'Adding two-digit numbers',area:'N',dfe:'4, 5',vq:'adding two digit numbers column addition',
 lesson:{idea:'To add two-digit numbers, add the ones and the tens separately.',steps:['Write the numbers in columns: tens under tens, ones under ones.','Add the ones first.','If the ones make 10 or more, carry 1 ten across.','Then add the tens.'],ex:{q:'47 + 35',w:['Ones: 7 + 5 = 12. Write 2, carry 1 ten.','Tens: 4 + 3 + 1 = 8.','47 + 35 = 82']},trap:'Do not forget the ten you carried.'},
 gens:[()=>{const a=rnd(11,89),b=rnd(11,99);return{text:`Work out <span class="fm">${a} + ${b}</span>`,ans:a+b,steps:[`Ones: ${a%10} + ${b%10} = ${a%10+b%10}${a%10+b%10>9?' (carry 1 ten)':''}`,`Tens: ${Math.floor(a/10)} + ${Math.floor(b/10)}${a%10+b%10>9?' + 1':''} = ${Math.floor((a+b)/10)}`,`${a} + ${b} = <b>${a+b}</b>`]};},
  ()=>{const a=rnd(12,60),b=rnd(12,39),[x,y]=pick([['plants in the polytunnel','in the garden'],['people on the morning trip','on the afternoon trip'],['screws in a tub','in a box']]);return{text:`There are ${a} ${x} and ${b} ${y}. How many are there in total?`,ans:a+b,steps:['In total means add.',`${a} + ${b} = <b>${a+b}</b>`]};}]});

topic('e2-sub',{b:1,s:5,title:'Subtracting two-digit numbers',area:'N',dfe:'4, 5',vq:'subtracting two digit numbers column subtraction',
 lesson:{idea:'To subtract two-digit numbers, take away the ones and the tens separately.',steps:['Write the bigger number on top, in columns.','Take away the ones first.','If the top ones digit is too small, swap 1 ten for 10 ones.','Then take away the tens.','Check by adding your answer to the number you took away.'],ex:{q:'63 − 28',w:['Ones: 3 − 8 will not go. Swap a ten: 13 − 8 = 5.','Tens: 5 − 2 = 3.','63 − 28 = 35','Check: 35 + 28 = 63.']},trap:'Always take the bottom digit from the top digit, never the other way round.'},
 gens:[()=>{const a=rnd(30,99),b=rnd(11,a-5);return{text:`Work out <span class="fm">${a} − ${b}</span>`,ans:a-b,steps:[`Count back the tens: ${a} − ${Math.floor(b/10)*10} = ${a-Math.floor(b/10)*10}`,`Then the ones: ${a-Math.floor(b/10)*10} − ${b%10} = <b>${a-b}</b>`,`Check: ${a-b} + ${b} = ${a}`]};},
  ()=>{const a=rnd(40,99),b=rnd(12,a-10),n=who();return{text:`${n} has ${a} fence posts. ${n} uses ${b} of them. How many are left?`,ans:a-b,steps:['Left means subtract.',`${a} − ${b} = <b>${a-b}</b>`]};}]});

const r10=n=>Math.round(n/10)*10;
topic('e2-round',{b:1,s:6,title:'Rounding to the nearest 10',area:'N',dfe:'9',vq:'rounding to the nearest 10',
 lesson:{idea:'Rounding gives a simpler number that is close enough. You can use it to check whether an answer is sensible.',steps:['Look at the ones digit.','If it is 5 or more, round up to the next ten.','If it is 4 or less, round down.','To check a sum, round each number and add the rounded numbers.'],ex:{q:'Round 67 to the nearest 10.',w:['67 is between 60 and 70.','The ones digit is 7, which is 5 or more.','Round up to 70.']},trap:'A number ending in 5 rounds up. 45 rounds to 50.'},
 gens:[()=>{let n;do{n=rnd(11,199);}while(n%10===0);return{text:`Round ${n} to the nearest 10.`,ans:r10(n),fig:figNumLine(Math.floor(n/10)*10,Math.floor(n/10)*10+10,1,{mark:[n],every:5}),steps:[`${n} is between ${Math.floor(n/10)*10} and ${Math.floor(n/10)*10+10}.`,`The ones digit is ${n%10}, so round ${n%10>=5?'up':'down'}: <b>${r10(n)}</b>`]};},
  ()=>{let a,b;do{a=rnd(12,68);b=rnd(12,68);}while(a%10===0||b%10===0);return{text:`Estimate ${a} + ${b} by rounding each number to the nearest 10 first.`,ans:r10(a)+r10(b),steps:[`${a} rounds to ${r10(a)}. ${b} rounds to ${r10(b)}.`,`${r10(a)} + ${r10(b)} = <b>${r10(a)+r10(b)}</b>`]};},
  ()=>{let a,b;do{a=rnd(21,58);b=rnd(21,38);}while(a%10===0||b%10===0);const ok=rnd(0,1)===1,said=ok?a+b:a+b+pick([20,30,-20]),n=who();return{text:`${n} works out ${a} + ${b} = ${said}. Round each number to the nearest 10 to check. Does ${n}'s answer look right?`,kind:'choice',opts:['Yes, it is close to the estimate','No, it is too far from the estimate'],ans:ok?0:1,steps:[`Estimate: ${r10(a)} + ${r10(b)} = ${r10(a)+r10(b)}.`,`${n}'s answer is ${said}. ${ok?'That is close, so it looks right.':'That is not close, so it is probably wrong.'}`]};}]});

topic('e2-mult',{b:2,s:7,title:'Times tables',area:'N',dfe:'4, 6',vq:'times tables multiplication facts',
 lesson:{idea:'Multiplying is a quick way of adding the same number again and again. 4 × 3 means 4 lots of 3.',steps:['Picture equal groups: 4 bags with 3 in each.','Count in steps: 3, 6, 9, 12.','Learn the tables so you can answer straight away.','You can swap the numbers: 4 × 3 is the same as 3 × 4.'],ex:{q:'6 × 5',w:['6 lots of 5.','Count in fives: 5, 10, 15, 20, 25, 30.','6 × 5 = 30']},trap:'Anything times 0 is 0. Anything times 1 stays the same.'},
 gens:[()=>{const a=rnd(0,12),b=rnd(2,12);return{text:`Work out <span class="fm">${a} × ${b}</span>`,ans:a*b,steps:[`${a} lots of ${b}.`,`${a} × ${b} = <b>${a*b}</b>`]};},
  ()=>{const g=rnd(2,6),s=pick([2,3,4,5,10]);return{text:`There are ${g} trays with ${s} in each tray. How many altogether?`,fig:figGroups(g,s),ans:g*s,steps:[`${g} lots of ${s}.`,`${g} × ${s} = <b>${g*s}</b>`]};},
  ()=>{const a=rnd(3,12),b=pick([2,3,4,5,6,8,10]),[x,y]=pick([['boxes','eggs'],['packs','batteries'],['tables','chairs'],['crates','bottles']]);return{text:`There are ${a} ${x}. Each one has ${b} ${y}. How many ${y} are there?`,ans:a*b,steps:['Equal groups means multiply.',`${a} × ${b} = <b>${a*b}</b>`]};}]});

topic('e2-div',{b:2,s:8,title:'Dividing and remainders',area:'N',dfe:'4, 8',vq:'division with remainders sharing grouping',
 lesson:{idea:'Dividing means sharing equally or making equal groups. Sometimes there are some left over. That is the remainder.',steps:['Use your times tables. For 20 ÷ 5 ask "how many 5s make 20?"','If it does not go exactly, find the closest table fact below it.','What is left over is the remainder.'],ex:{q:'17 ÷ 5',w:['3 × 5 = 15. That is the closest without going over.','17 − 15 = 2 left over.','17 ÷ 5 = 3 remainder 2']},trap:'The remainder must be smaller than the number you are dividing by.'},
 gens:[()=>{const d=rnd(2,9),q=rnd(2,11);return{text:`Work out <span class="fm">${d*q} ÷ ${d}</span>`,ans:q,steps:[`How many ${d}s make ${d*q}?`,`${q} × ${d} = ${d*q}, so the answer is <b>${q}</b>.`]};},
  ()=>{const d=rnd(3,9),q=rnd(2,10),r=rnd(1,d-1),n=d*q+r,th=pick(['bread rolls','cakes','plants','bottles']);return{text:`${n} ${th} are packed into boxes of ${d}. How many <b>full</b> boxes are there?`,ans:q,steps:[`${q} × ${d} = ${d*q}. One more box would need ${d*(q+1)}.`,`There are <b>${q}</b> full boxes, with ${r} left over.`]};},
  ()=>{const d=rnd(3,9),q=rnd(2,10),r=rnd(1,d-1),n=d*q+r;return{text:`${n} ÷ ${d} = ${q} remainder ☐<br>What is the remainder?`,ans:r,steps:[`${q} × ${d} = ${d*q}`,`${n} − ${d*q} = <b>${r}</b> left over.`]};}]});

topic('e2-halves',{b:2,s:9,title:'Halves and quarters',area:'N',dfe:'10',vq:'halves and quarters of shapes and numbers',
 lesson:{idea:'A fraction is an equal part of something. A half is 1 of 2 equal parts. A quarter is 1 of 4 equal parts.',steps:['To find a half, divide by 2.','To find a quarter, divide by 4. You can also halve it, then halve it again.','A half is written ½. A quarter is written ¼.'],ex:{q:'Find a quarter of 20.',w:['Half of 20 is 10.','Half of 10 is 5.','A quarter of 20 is 5.']},trap:'The parts must be equal. Two pieces of different sizes are not halves.'},
 gens:[()=>{const h=rnd(0,1)===1,n=(h?2:4)*rnd(2,12);return{text:`Find ${h?'half':'a quarter'} of ${n}.`,ans:n/(h?2:4),steps:[h?`Divide by 2.`:`Divide by 4, or halve it twice.`,`${n} ÷ ${h?2:4} = <b>${n/(h?2:4)}</b>`]};},
  ()=>{const[n,d]=pick([[1,2],[1,4],[3,4],[2,4]]),lab=n===2?'One half':n===1&&d===2?'One half':n===1?'One quarter':'Three quarters';return{text:'What fraction of the bar is shaded?',fig:figFrac(n,d),...mc(lab,['One half','One quarter','Three quarters','One tenth'].filter(x=>x!==lab).slice(0,3)),steps:[`The bar has ${d} equal parts. ${n} ${n===1?'is':'are'} shaded.`,`That is <b>${lab.toLowerCase()}</b>.`]};},
  ()=>{const n=4*rnd(2,10),th=pick(['sweets','stickers','biscuits','cards']),k=who();return{text:`${k} has ${n} ${th} and gives half of them away. How many does ${k} give away?`,ans:n/2,steps:['Half means divide by 2.',`${n} ÷ 2 = <b>${n/2}</b>`]};}]});

topic('e2-tenths',{b:2,s:10,title:'Tenths and decimals',area:'N',dfe:'10, 11',vq:'tenths decimals one decimal place',
 lesson:{idea:'If you cut one whole into 10 equal parts, each part is one tenth. A tenth is written 0.1 as a decimal.',steps:['The decimal point separates whole ones from tenths.','0.3 means 3 tenths. 2.5 means 2 whole ones and 5 tenths.','To compare, look at the whole number first, then the tenths.'],ex:{q:'Write 7 tenths as a decimal.',w:['There are no whole ones, so start with 0.','Put the 7 after the point.','0.7']},trap:'0.5 is a half. It is five tenths, not five.'},
 gens:[()=>{const n=rnd(1,9);return{text:'What part of the bar is shaded? Give your answer as a decimal.',fig:figFrac(n,10,280),ans:n/10,steps:[`${n} out of 10 equal parts are shaded. That is ${n} tenths.`,`As a decimal: <b>0.${n}</b>`]};},
  ()=>{const w=rnd(0,3),n=rnd(1,9),v=rd(w+n/10,1);return{text:'What number is the arrow pointing to?',fig:figNumLine(w,w+1,0.1,{mark:[v],every:10}),ans:v,steps:[`Each small step is one tenth (0.1).`,`The arrow is ${n} steps after ${w}: <b>${v}</b>`]};},
  ()=>{let a,b;do{a=rnd(1,49);b=rnd(1,49);}while(b===a||a%10===0||b%10===0);const big=rnd(0,1)===1,t=big?Math.max(a,b):Math.min(a,b);return{text:`Which is ${big?'bigger':'smaller'}?`,...mc(String(t/10),[String((a+b-t)/10)]),steps:['Compare the whole numbers first, then the tenths.',`<b>${t/10}</b> is ${big?'bigger':'smaller'}.`]};},
  ()=>{const n=rnd(1,9);return{text:`Write ${words(n)} tenths as a decimal.`,ans:n/10,steps:['No whole ones, so start with 0 and a point.',`<b>0.${n}</b>`]};}]});

topic('e2-choose',{b:2,s:11,title:'Choosing the right sum',area:'N',dfe:'4',vq:'choosing operation word problems four operations',
 lesson:{idea:'There are four kinds of sum: add (+), subtract (−), multiply (×) and divide (÷). The words in the problem tell you which one to use.',steps:['"Altogether" and "total" usually mean add.','"Left" and "difference" mean subtract.','"Each" with equal groups means multiply.','"Share" and "split equally" mean divide.'],ex:{q:'24 biscuits are shared equally between 6 people. How many each?',w:['"Shared equally" means divide.','24 ÷ 6 = 4','4 biscuits each.']},trap:'Read the question twice. Decide the sum before you pick up the numbers.'},
 gens:[()=>{const P=[['+',`A van carries 34 boxes in the morning and 25 in the afternoon. Which sign do you use to find the total?`,'Total means add.'],['−',`There are 60 chairs. 18 are taken away. Which sign do you use to find how many are left?`,'Left means subtract.'],['×',`There are 7 packs with 6 cans in each. Which sign do you use to find the number of cans?`,'Equal groups means multiply.'],['÷',`36 seedlings are shared equally between 4 trays. Which sign do you use to find the number in each tray?`,'Shared equally means divide.']],i=rnd(0,3);return{text:P[i][1],kind:'choice',opts:['+','−','×','÷'],ans:i,steps:[P[i][2],`The sign is <b>${P[i][0]}</b>.`]};},
  ()=>{const m=rnd(0,3),n=who();if(m===0){const a=rnd(15,50),b=rnd(12,40);return{text:`${n} cycles ${a} km on Saturday and ${b} km on Sunday. How far is that altogether?`,ans:a+b,suf:'km',steps:['Altogether means add.',`${a} + ${b} = <b>${a+b} km</b>`]};}
   if(m===1){const a=rnd(40,90),b=rnd(12,35);return{text:`A roll has ${a} metres of rope. ${n} cuts off ${b} metres. How much is left?`,ans:a-b,suf:'m',steps:['Left means subtract.',`${a} − ${b} = <b>${a-b} m</b>`]};}
   if(m===2){const a=rnd(3,9),b=rnd(3,9);return{text:`${n} plants ${a} rows of cabbages with ${b} in each row. How many cabbages?`,ans:a*b,steps:['Equal rows means multiply.',`${a} × ${b} = <b>${a*b}</b>`]};}
   const d=rnd(3,8),q=rnd(3,9);return{text:`${d*q} tools are shared equally between ${d} groups. How many tools does each group get?`,ans:q,steps:['Shared equally means divide.',`${d*q} ÷ ${d} = <b>${q}</b>`]};}]});

topic('e2-money',{b:3,s:13,title:'Adding up money',area:'M',dfe:'12',vq:'adding money pence and pounds',
 lesson:{idea:'Add pence to pence and pounds to pounds. There are 100 pence in £1.',steps:['For pence, add the prices like normal numbers and write p.','For several things at the same whole-pound price, multiply.','Change is what you paid take away the cost.'],ex:{q:'A drink is 45p and an apple is 30p. What is the total?',w:['45 + 30 = 75','The total is 75p.']},trap:'Write either £ or p, never both. 75p is right. £75p is wrong.'},
 gens:[()=>{let a,b;do{[a,b]=pickN(SNACKS,2);}while(a[1]+b[1]>100);return{text:`A ${a[0]} costs ${a[1]}p and a ${b[0]} costs ${b[1]}p. How much do they cost altogether?`,ans:a[1]+b[1],suf:'p',steps:[`${a[1]} + ${b[1]}`,`= <b>${a[1]+b[1]}p</b>`]};},
  ()=>{const n=rnd(2,9),p=pick([2,3,4,5,6,8,10,12]),it=pick(['tickets','T-shirts','plants','torches','mugs']);return{text:`${cap(it)} cost £${p} each. How much do ${n} ${it} cost?`,ans:n*p,pre:'£',steps:[`${n} lots of £${p}.`,`${n} × ${p} = <b>£${n*p}</b>`]};},
  ()=>{const p=rnd(4,19)*5;return{text:`You buy something for ${p}p and pay with a £1 coin. How much change do you get?`,ans:100-p,suf:'p',steps:['£1 is 100p.',`100 − ${p} = <b>${100-p}p</b>`]};}]});

topic('e2-dates',{b:3,s:14,title:'Dates and time facts',area:'M',dfe:'7, 13',vq:'reading dates calendar hours in a day',
 lesson:{idea:'Dates can be written in words, like 5 March 2026, or in numbers, like 05/03/2026. In the UK the day comes first, then the month, then the year.',steps:['In 05/03/2026 the day is 5 and the month is 3, which is March.','There are 24 hours in a day and 7 days in a week.','There are 52 weeks and 12 months in a year.'],ex:{q:'What date is 12/08/2026?',w:['Day 12.','Month 8 is August.','12 August 2026']},trap:'In the UK 03/05 is 3 May, not 5 March. The day always comes first.'},
 gens:[()=>{const F=[['hours are there in a day',24],['weeks are there in a year',52],['days are there in a week',7],['months are there in a year',12]],[q,a]=pick(F);return{text:`How many ${q}?`,ans:a,steps:[`There are <b>${a}</b>.`]};},
  ()=>{let d,m;do{d=rnd(1,12);m=rnd(1,12);}while(d===m);const y=pick(NEAR_YEARS()),p=x=>String(x).padStart(2,'0');return{text:`A letter is dated <b>${p(d)}/${p(m)}/${y}</b>. What date is that?`,...mc(`${d} ${MONTHS[m-1]} ${y}`,[`${m} ${MONTHS[d-1]} ${y}`,`${d} ${MONTHS[m%12]} ${y}`]),steps:[`The day comes first: ${d}.`,`Month ${m} is ${MONTHS[m-1]}.`,`<b>${d} ${MONTHS[m-1]} ${y}</b>`]};},
  ()=>{const d=rnd(13,28),m=rnd(1,12),y=pick(NEAR_YEARS()),p=x=>String(x).padStart(2,'0');return{text:`How do you write <b>${d} ${MONTHS[m-1]} ${y}</b> in numbers?`,...mc(`${p(d)}/${p(m)}/${y}`,[`${p(m)}/${p(d)}/${y}`,`${p(d)}/${p(m%12+1)}/${y}`,`${y}/${p(d)}/${p(m)}`]),steps:[`Day ${d}, then month ${m}, then the year.`,`<b>${p(d)}/${p(m)}/${y}</b>`]};}]});

const sayTime=(h,m)=>m===0?`${h} o'clock`:m===15?`Quarter past ${h}`:m===30?`Half past ${h}`:`Quarter to ${h%12+1}`;
topic('e2-clock',{b:3,s:15,title:'Half past, quarter past and 24-hour time',area:'M',dfe:'13',vq:'telling time half past quarter past quarter to',
 lesson:{idea:'The long hand shows the minutes. When it has gone half way round, it is half past. A quarter of the way is quarter past.',steps:['Long hand on 12: o\'clock. On 3: quarter past. On 6: half past. On 9: quarter to the next hour.','The short hand shows the hour. At half past it sits half way between two numbers.','On a 24-hour clock the afternoon hours carry on: 13:00 is 1 pm, 15:00 is 3 pm.'],ex:{q:'The long hand is on 6. The short hand is between 4 and 5. What time is it?',w:['Long hand on 6 means half past.','The short hand has gone past 4.','It is half past 4.']},trap:'"Quarter to 5" is before 5. The short hand is nearly at 5, not at 4.'},
 gens:[()=>{const h=rnd(1,12),m=pick([0,15,30,45]),o=[0,15,30,45].map(x=>sayTime(h,x));return{text:'What time does the clock show?',fig:figClock(h,m),kind:'choice',opts:o,ans:[0,15,30,45].indexOf(m),steps:[`The long hand points to ${m===0?12:m/5}. That means ${['o\'clock','quarter past','half past','quarter to'][m/15]}.`,`The time is <b>${sayTime(h,m).toLowerCase()}</b>.`]};},
  ()=>{const h=rnd(13,23);return{text:'This is a 24-hour clock. What time is it?',fig:figDigital(h+':00'),...mcn(h-12,[h-10,h-11,h-13,h-14].filter(x=>x>=1&&x<=12),x=>`${x} o'clock in the ${h<18?'afternoon':'evening'}`),hint:'For hours after 12, take away 12.',steps:[`${h} − 12 = ${h-12}`,`It is <b>${h-12} o'clock in the ${h<18?'afternoon':'evening'}</b>.`]};},
  ()=>{const h=rnd(1,12),m=pick([15,30,45]);return{text:`Which digital time is the same as "${sayTime(h,m).toLowerCase()}"?`,...mc(m===45?t12(h,45):t12(h,m),[t12(h,m===30?15:30),t12(h%12+1,m),t12(h,m===45?15:45)].filter((x,i,a)=>a.indexOf(x)===i)),steps:[`${['','Quarter past is 15 minutes past.','Half past is 30 minutes past.','Quarter to is 45 minutes past the hour before.'][m/15]}`,`<b>${t12(h,m)}</b>`]};}]});

topic('e2-length',{b:3,s:16,title:'Measuring length',area:'M',dfe:'14',vq:'measuring length mm cm m km',
 lesson:{idea:'Length is measured in millimetres (mm), centimetres (cm), metres (m) and kilometres (km).',steps:['Millimetres are tiny: a coin is about 2 mm thick.','Centimetres are about the width of a finger. A ruler is 30 cm.','A metre is about one big step. A door is about 2 m tall.','Kilometres are for long distances between places.'],ex:{q:'What would you use to measure the distance from Truro to Penzance?',w:['It is a long journey between two towns.','Long distances use kilometres.']},trap:'Always start measuring from the 0 mark on the ruler, not from the end of the ruler.'},
 gens:[()=>{const[q,a]=pick([['the distance between two towns','Kilometres (km)'],['the length of a football pitch','Metres (m)'],['the length of a pencil','Centimetres (cm)'],['the thickness of a phone screen','Millimetres (mm)'],['the height of a door','Metres (m)'],['the width of a book','Centimetres (cm)'],['the length of a walk along the coast path','Kilometres (km)'],['the width of a screw head','Millimetres (mm)']]);return{text:`Which unit is best for measuring ${q}?`,...mct(a,['Millimetres (mm)','Centimetres (cm)','Metres (m)','Kilometres (km)']),steps:[`Think about how big it is.`,`The best unit is <b>${a.toLowerCase()}</b>.`]};},
  ()=>{const v=rnd(2,14);return{text:'A nail is measured from 0 on this ruler. The arrow shows where it ends. How long is the nail?',fig:figScale({min:0,max:15,major:1,minor:1,val:v,unit:'cm'}),ans:v,suf:'cm',steps:['Read the number under the arrow.',`The nail is <b>${v} cm</b> long.`]};},
  ()=>{const[q,a]=pick([['centimetres are there in 1 metre',100],['millimetres are there in 1 centimetre',10],['metres are there in 1 kilometre',1000]]);return{text:`How many ${q}?`,ans:a,steps:[`There are <b>${nf(a)}</b>.`]};}]});

topic('e2-weight',{b:3,s:17,title:'Measuring weight',area:'M',dfe:'15',vq:'measuring weight grams kilograms',
 lesson:{idea:'Weight is measured in grams (g) and kilograms (kg). There are 1000 grams in 1 kilogram.',steps:['Grams are for light things. A paperclip is about 1 g. An apple is about 150 g.','Kilograms are for heavier things. A bag of sugar is 1 kg.','Read the label or the scale, and always write the unit.'],ex:{q:'Would you weigh a bag of potatoes in grams or kilograms?',w:['A bag of potatoes is heavy.','Use kilograms.']},trap:'500 g is less than 1 kg, even though 500 is a bigger number than 1.'},
 gens:[()=>{const[q,a]=pick([['a bag of cement','kg'],['a letter','g'],['a person','kg'],['a teaspoon of salt','g'],['a wheelbarrow of soil','kg'],['a pencil','g'],['a dog','kg'],['a slice of bread','g']]);return{text:`Which unit would you use to weigh ${q}?`,kind:'choice',opts:['Grams (g)','Kilograms (kg)'],ans:a==='g'?0:1,steps:[a==='g'?'It is light, so use grams.':'It is heavy, so use kilograms.',`<b>${a==='g'?'Grams':'Kilograms'}</b>`]};},
  ()=>{const v=rnd(1,9);return{text:'A parcel is put on the scales. What does it weigh?',fig:figScale({min:0,max:10,major:1,minor:1,val:v,unit:'kg'}),ans:v,suf:'kg',steps:['Read the number under the arrow.',`The parcel weighs <b>${v} kg</b>.`]};},
  ()=>{let a=rnd(2,18)*50,b;do{b=rnd(2,18)*50;}while(a===b);const hv=rnd(0,1)===1,t=hv?Math.max(a,b):Math.min(a,b);return{text:`One tin weighs ${a} g. Another weighs ${b} g. Which is ${hv?'heavier':'lighter'}?`,...mc(`The ${t} g tin`,[`The ${a+b-t} g tin`]),steps:['Both are in grams, so compare the numbers.',`<b>${t} g</b> is ${hv?'heavier':'lighter'}.`]};}]});

topic('e2-capacity',{b:3,s:18,title:'Measuring capacity',area:'M',dfe:'16',vq:'measuring capacity millilitres litres',
 lesson:{idea:'Capacity is how much liquid something holds. It is measured in millilitres (ml) and litres. There are 1000 ml in 1 litre.',steps:['Millilitres are for small amounts. A teaspoon holds 5 ml. A can of drink is 330 ml.','Litres are for bigger amounts. A big bottle of milk is 2 litres.','On a jug, read the line the liquid reaches.'],ex:{q:'Would you measure the water in a bath in millilitres or litres?',w:['A bath holds a lot of water.','Use litres.']},trap:'Read a jug with your eyes level with the liquid, not from above.'},
 gens:[()=>{const[q,a]=pick([['a watering can','l'],['a spoonful of medicine','ml'],['a paddling pool','l'],['a cup of tea','ml'],['a bucket','l'],['an egg cup','ml'],['a fuel can','l'],['a small glass of juice','ml']]);return{text:`Which unit would you use to measure how much ${q} holds?`,kind:'choice',opts:['Millilitres (ml)','Litres'],ans:a==='ml'?0:1,steps:[a==='ml'?'It holds a small amount, so use millilitres.':'It holds a large amount, so use litres.',`<b>${a==='ml'?'Millilitres':'Litres'}</b>`]};},
  ()=>{const v=rnd(1,9)*100;return{text:'How much water is in the jug?',fig:figScale({min:0,max:1000,major:100,minor:100,val:v,unit:'ml',vert:true,jug:true}),ans:v,suf:'ml',steps:['Find the top of the water and read the number next to it.',`There is <b>${v} ml</b>.`]};},
  ()=>{let a=rnd(1,9),b;do{b=rnd(1,9);}while(a===b);const m=rnd(0,1)===1,t=m?Math.max(a,b):Math.min(a,b);return{text:`A red bucket holds ${a} litres. A blue bucket holds ${b} litres. Which holds ${m?'more':'less'}?`,...mc(a===t?'The red bucket':'The blue bucket',[a===t?'The blue bucket':'The red bucket']),steps:[`${Math.max(a,b)} litres is more than ${Math.min(a,b)} litres.`,`<b>${a===t?'The red bucket':'The blue bucket'}</b> holds ${m?'more':'less'}.`]};}]});

topic('e2-scales',{b:4,s:19,title:'Reading scales',area:'M',dfe:'18',vq:'reading scales measuring',
 lesson:{idea:'Rulers, weighing scales and jugs all have a scale: a line of marks with numbers.',steps:['Find where the arrow or the liquid reaches.','Read the number at that mark.','Write the unit: cm, kg, ml and so on.'],ex:{q:'The arrow on a scale points to the mark labelled 40. The scale is in grams.',w:['Read the number: 40.','Add the unit.','40 g']},trap:'Check what the scale counts up in. It might go up in 10s or 50s, not 1s.'},
 gens:[()=>{const st=pick([5,10,20,50]),v=rnd(1,9)*st,u=pick(['g','kg','cm']);return{text:'What does the arrow point to on this scale?',fig:figScale({min:0,max:10*st,major:st,minor:st,val:v,unit:u}),ans:v,suf:u,steps:[`The scale goes up in ${st}s.`,`The arrow points to <b>${v} ${u}</b>.`]};},
  ()=>{const st=pick([50,100,200]),v=rnd(1,9)*st;return{text:'How much liquid is in the jug?',fig:figScale({min:0,max:10*st,major:st,minor:st,val:v,unit:'ml',vert:true,jug:true}),ans:v,suf:'ml',steps:[`The marks go up in ${st}s.`,`The liquid reaches <b>${nf(v)} ml</b>.`]};},
  ()=>{const st=pick([10,20]),a=rnd(1,4)*st,b=rnd(5,9)*st;return{text:`A scale shows ${a} kg for one sack and ${b} kg for another. Which reading is heavier?`,...mc(`${b} kg`,[`${a} kg`]),steps:['Both readings are in kg.',`<b>${b} kg</b> is heavier than ${a} kg.`]};}]});

topic('e2-temp',{b:4,s:20,title:'Temperature',area:'M',dfe:'17',vq:'reading thermometer temperature degrees celsius',
 lesson:{idea:'Temperature tells you how hot or cold something is. It is measured in degrees Celsius, written °C.',steps:['A bigger number is warmer. A smaller number is colder.','Water freezes at 0°C. A warm room is about 20°C.','On a thermometer, read the number at the top of the coloured line.'],ex:{q:'It is 8°C in the morning and 15°C in the afternoon. Which is warmer?',w:['15 is bigger than 8.','The afternoon is warmer.']},trap:'Read the top of the coloured line, not the top of the tube.'},
 gens:[()=>{const v=rnd(1,7)*5;return{text:'What temperature does the thermometer show?',fig:figScale({min:0,max:40,major:5,minor:5,val:v,unit:'°C',vert:true}),ans:v,suf:'°C',steps:['Read the number at the top of the coloured line.',`It shows <b>${v}°C</b>.`]};},
  ()=>{const pl=pickN(['Truro','Leeds','Cardiff','Derby','Hull','Perth','Bath','York'],2);let a=rnd(2,28),b;do{b=rnd(2,28);}while(a===b);const w=rnd(0,1)===1,t=w?Math.max(a,b):Math.min(a,b);return{text:`It is ${a}°C in ${pl[0]} and ${b}°C in ${pl[1]}. Which place is ${w?'warmer':'colder'}?`,...mc(a===t?pl[0]:pl[1],[a===t?pl[1]:pl[0]]),steps:[`${Math.max(a,b)} is bigger than ${Math.min(a,b)}.`,`<b>${a===t?pl[0]:pl[1]}</b> is ${w?'warmer':'colder'}.`]};},
  ()=>{const t=pickN([...Array(30).keys()].map(x=>x+1),4),hot=rnd(0,1)===1,r=hot?Math.max(...t):Math.min(...t);return{text:`Which of these temperatures is the ${hot?'hottest':'coldest'}?`,...mc(r+'°C',t.filter(x=>x!==r).map(x=>x+'°C')),steps:[`In order: ${t.slice().sort((a,b)=>a-b).map(x=>x+'°C').join(', ')}.`,`The ${hot?'hottest':'coldest'} is <b>${r}°C</b>.`]};}]});

topic('e2-shapes',{b:4,s:21,title:'Naming 2D and 3D shapes',area:'M',dfe:'19',vq:'naming 2D and 3D shapes pentagon hexagon cylinder',
 lesson:{idea:'Flat shapes are named by how many sides they have. Solid shapes have their own names.',steps:['Triangle: 3 sides. Square and rectangle: 4. Pentagon: 5. Hexagon: 6.','Cuboid: a box. Cylinder: a tube with round ends. Sphere: a ball.','Pyramid: flat base and triangle sides that meet at a point.'],ex:{q:'A flat shape has 6 straight sides. What is it?',w:['Count the sides: 6.','A 6-sided shape is a hexagon.']},trap:'Pentagon has 5 sides, like the 5 letters in "penta". Hexagon has 6, and both "hexagon" and "six" have an x.'},
 gens:[()=>{const n=pick(SHAPES2);return{text:'What is this flat shape called?',fig:figShape(n),...mct(cap(n),SHAPES2.map(cap)),steps:[n==='circle'?'It is round.':`Count the sides.`,`It is a <b>${n}</b>.`]};},
  ()=>{const n=pick(SHAPES3);return{text:'What is this solid shape called?',fig:figShape(n),...mct(cap(n),SHAPES3.map(cap)),steps:[{cube:'All its faces are squares.',cuboid:'It is a box with rectangle faces.',cylinder:'It has two circle ends.',sphere:'It is a ball.',pyramid:'Its sides are triangles that meet at a point.',cone:'It has a circle base and comes to a point.'}[n],`It is a <b>${n}</b>.`]};},
  ()=>{const[ob,n]=pick([['A tin of paint','Cylinder'],['A tennis ball','Sphere'],['A shoe box','Cuboid'],['A dice','Cube'],['A traffic cone','Cone'],['A tent with a square floor and a pointed top','Pyramid']]);return{text:`${ob} is which shape?`,...mct(n,SHAPES3.map(cap)),steps:[`${ob} is a <b>${n.toLowerCase()}</b>.`]};}]});

topic('e2-props',{b:4,s:22,title:'Sides, corners, faces and edges',area:'M',dfe:'20',vq:'properties of shapes faces edges vertices',
 lesson:{idea:'We describe shapes by counting their parts.',steps:['Flat shapes have sides and corners. A square has 4 sides and 4 corners.','Solid shapes have faces (the flat surfaces), edges (where two faces meet) and corners.','The base is the face a solid sits on.'],ex:{q:'How many faces does a cube have?',w:['Think of a dice.','It has numbers 1 to 6, one on each face.','A cube has 6 faces.']},trap:'Count carefully and remember the faces you cannot see at the back and underneath.'},
 gens:[()=>{const P={triangle:3,square:4,rectangle:4,pentagon:5,hexagon:6},n=pick(Object.keys(P)),sd=rnd(0,1)===1;return{text:`How many ${sd?'sides':'corners'} does a ${n} have?`,fig:figShape(n),ans:P[n],steps:[`Count round the shape.`,`A ${n} has <b>${P[n]}</b> ${sd?'sides':'corners'}.`]};},
  ()=>{const P={cube:[6,12,8],cuboid:[6,12,8],pyramid:[5,8,5]},n=pick(Object.keys(P)),i=rnd(0,2);return{text:`How many ${['faces','edges','corners'][i]} does a ${n==='pyramid'?'square-based pyramid':n} have?`,fig:figShape(n),ans:P[n][i],steps:[n==='pyramid'?'It has 1 square base and 4 triangle faces.':'Think of a box: top, bottom and 4 sides.',`It has <b>${P[n][i]}</b> ${['faces','edges','corners'][i]}.`]};},
  ()=>{const Q=[['has 6 square faces','Cube'],['has no corners and no edges','Sphere'],['has 2 circle faces and 1 curved face','Cylinder'],['has a square base and 4 triangle faces','Pyramid'],['has 5 sides and 5 corners','Pentagon'],['has 6 sides and 6 corners','Hexagon']],[d,a]=pick(Q);return{text:`Which shape ${d}?`,...mct(a,Q.map(x=>x[1])),steps:[`A <b>${a.toLowerCase()}</b> ${d}.`]};}]});

topic('e2-pos',{b:4,s:23,title:'Position and movement',area:'M',dfe:'21',vq:'position vocabulary between inside outside',
 lesson:{idea:'Position words tell you where something is. Movement words tell you which way to go.',steps:['Between means in the middle of two things.','Inside is in it. Outside is not in it.','On top is the highest one. Below is lower down.','Forwards is the way you are facing. Backwards is the opposite way.'],ex:{q:'You are on step 6 and move 2 steps backwards. Where are you?',w:['Backwards means the numbers go down.','6 − 2 = 4','You are on step 4.']},trap:'Between needs two things: the bench is between the shed and the gate.'},
 gens:[()=>{const n=pickN(['Shed','Gate','Bench','Pond','Tree'],3);return{text:`What is between the ${n[0].toLowerCase()} and the ${n[2].toLowerCase()}?`,fig:figCards(n),...mc(n[1],[n[0],n[2]]),steps:['Between means in the middle of the two.',`The <b>${n[1].toLowerCase()}</b> is between them.`]};},
  ()=>{const n=pickN(['Box','Crate','Bag','Tub','Tray'],3),i=rnd(0,2);return{text:`Three things are stacked up. Which one is ${['on top','in the middle','at the bottom, below the others'][i]}?`,fig:figCards(n,true),...mc(n[i],n.filter((_,k)=>k!==i)),steps:[`Top: ${n[0]}. Middle: ${n[1]}. Bottom: ${n[2]}.`,`The answer is the <b>${n[i].toLowerCase()}</b>.`]};},
  ()=>{const s=rnd(4,12),k=rnd(1,3),f=rnd(0,1)===1,n=who();return{text:`A path has numbered squares. ${n} is on square ${s} and moves ${k} ${k===1?'square':'squares'} ${f?'forwards':'backwards'}. Which square is ${n} on now?`,fig:figNumLine(s-4,s+4,1),ans:f?s+k:s-k,steps:[f?'Forwards means the numbers go up.':'Backwards means the numbers go down.',`${s} ${f?'+':'−'} ${k} = <b>${f?s+k:s-k}</b>`]};},
  ()=>{const ins=pickN(['Rope','Torch','Map','Whistle','Gloves'],4),q=rnd(0,3),isIn=q<2;return{text:`The kit bag has the ${ins[0].toLowerCase()} and the ${ins[1].toLowerCase()} in it. The ${ins[2].toLowerCase()} and the ${ins[3].toLowerCase()} are on the table next to it. Is the ${ins[q].toLowerCase()} inside or outside the bag?`,kind:'choice',opts:['Inside','Outside'],ans:isIn?0:1,steps:[`The ${ins[q].toLowerCase()} is ${isIn?'in the bag':'on the table, not in the bag'}.`,`It is <b>${isIn?'inside':'outside'}</b>.`]};}]});

const priceTable=()=>{const it=pickN([['Tea',2],['Soup',4],['Sandwich',5],['Jacket potato',6],['Cake',3],['Juice',2],['Pasty',4],['Salad',5]],4);return it;};
topic('e2-tables',{b:5,s:25,title:'Lists and tables',area:'D',dfe:'22',vq:'reading tables and timetables',
 lesson:{idea:'A table sorts information into rows and columns. The headings at the top tell you what each column shows.',steps:['Read the headings first.','Find the row you need.','Go across to the column you need. Where they meet is your answer.'],ex:{q:'A price list shows Soup £4 and Cake £3. How much is soup and cake?',w:['Find Soup: £4. Find Cake: £3.','4 + 3 = 7','£7']},trap:'Check you are reading from the right column.'},
 gens:[()=>{const t=priceTable(),i=rnd(0,3);return{text:`Look at the café price list. How much is ${t[i][0].toLowerCase()}?${tbl(['Item','Price'],t.map(x=>[x[0],'£'+x[1]]))}`,ans:t[i][1],pre:'£',steps:[`Find ${t[i][0]} and read across.`,`<b>£${t[i][1]}</b>`]};},
  ()=>{const t=priceTable(),[i,j]=pickN([0,1,2,3],2);return{text:`Look at the café price list. How much do ${t[i][0].toLowerCase()} and ${t[j][0].toLowerCase()} cost together?${tbl(['Item','Price'],t.map(x=>[x[0],'£'+x[1]]))}`,ans:t[i][1]+t[j][1],pre:'£',steps:[`${t[i][0]}: £${t[i][1]}. ${t[j][0]}: £${t[j][1]}.`,`${t[i][1]} + ${t[j][1]} = <b>£${t[i][1]+t[j][1]}</b>`]};},
  ()=>{const acts=pickN(['Kayaking','Bushcraft','Cooking','Woodwork','Climbing'],4),st=pickN([9,10,11,13,14],4).sort((a,b)=>a-b),rooms=pickN(['Yard','Barn','Kitchen','Workshop','Field'],4),i=rnd(0,3),ask=rnd(0,1);return{text:`Look at the timetable. ${ask?`Where is ${acts[i].toLowerCase()}?`:`Which activity starts at ${st[i]}:00?`}${tbl(['Activity','Starts','Place'],acts.map((a,k)=>[a,st[k]+':00',rooms[k]]))}`,...mc(ask?rooms[i]:acts[i],(ask?rooms:acts).filter((_,k)=>k!==i)),steps:[ask?`Find ${acts[i]} and read across to Place.`:`Find ${st[i]}:00 in the Starts column and read back to the activity.`,`<b>${ask?rooms[i]:acts[i]}</b>`]};}]});

const barData=(st)=>{const c=pickN(['Mon','Tue','Wed','Thu','Fri'],4).sort((a,b)=>['Mon','Tue','Wed','Thu','Fri'].indexOf(a)-['Mon','Tue','Wed','Thu','Fri'].indexOf(b)),v=pickN([1,2,3,4,5,6,7,8],4).map(x=>x*st);return{c,v,st,fig:figBars(c,v,{step:st,max:8*st,every:st===1?2:1,xl:'Day',yl:'Visitors'})};};
topic('e2-bars',{b:5,s:26,title:'Reading bar charts',area:'D',dfe:'22',vq:'reading bar charts',
 lesson:{idea:'A bar chart uses bars to show amounts. The taller the bar, the bigger the amount.',steps:['Read the title and the labels so you know what the chart shows.','Find the bar you need.','Go across from the top of the bar to the numbers at the side.'],ex:{q:'The bar for Tuesday reaches 30. How many visitors on Tuesday?',w:['Go to the top of the Tuesday bar.','Read across to the side: 30.','30 visitors.']},trap:'Check what the side numbers go up in. Each line might be worth 2, 5 or 10.'},
 gens:[()=>{const d=barData(pick([2,5,10])),i=rnd(0,3);return{text:`The bar chart shows visitors to a farm shop. How many visitors were there on ${d.c[i]}?`,fig:d.fig,ans:d.v[i],steps:[`Find the ${d.c[i]} bar and go across from its top.`,`It reaches <b>${d.v[i]}</b>.`]};},
  ()=>{const d=barData(pick([2,5,10])),i=rnd(0,3);return{text:`The bar chart shows visitors to a farm shop. On which day were there ${d.v[i]} visitors?`,fig:d.fig,...mc(d.c[i],d.c.filter((_,k)=>k!==i)),steps:[`Find ${d.v[i]} at the side and go across to the bar that stops there.`,`That is <b>${d.c[i]}</b>.`]};}]});

topic('e2-compare',{b:5,s:27,title:'Comparing bars',area:'D',dfe:'23',vq:'comparing data bar charts difference',
 lesson:{idea:'Bar charts make it easy to compare. You can see the biggest and smallest, and work out the difference between two bars.',steps:['The tallest bar is the most. The shortest is the least.','To find how many more, read both bars.','Take the smaller number away from the bigger number.'],ex:{q:'Monday has 40 visitors and Friday has 25. How many more on Monday?',w:['40 − 25 = 15','15 more on Monday.']},trap:'"How many more" means subtract. Do not add the two bars.'},
 gens:[()=>{let d,i,j;do{d=barData(pick([2,5,10]));[i,j]=pickN([0,1,2,3],2);}while(d.v[i]<=d.v[j]);return{text:`How many more visitors were there on ${d.c[i]} than on ${d.c[j]}?`,fig:d.fig,ans:d.v[i]-d.v[j],steps:[`${d.c[i]}: ${d.v[i]}. ${d.c[j]}: ${d.v[j]}.`,`${d.v[i]} − ${d.v[j]} = <b>${d.v[i]-d.v[j]}</b>`]};},
  ()=>{const d=barData(pick([2,5,10])),mx=rnd(0,1)===1,t=mx?Math.max(...d.v):Math.min(...d.v),i=d.v.indexOf(t);return{text:`Which day had the ${mx?'most':'fewest'} visitors?`,fig:d.fig,...mc(d.c[i],d.c.filter((_,k)=>k!==i)),steps:[`Look for the ${mx?'tallest':'shortest'} bar.`,`<b>${d.c[i]}</b> with ${t}.`]};},
  ()=>{const d=barData(pick([2,5,10])),[i,j]=pickN([0,1,2,3],2);return{text:`How many visitors were there on ${d.c[i]} and ${d.c[j]} altogether?`,fig:d.fig,ans:d.v[i]+d.v[j],steps:[`${d.c[i]}: ${d.v[i]}. ${d.c[j]}: ${d.v[j]}.`,`${d.v[i]} + ${d.v[j]} = <b>${d.v[i]+d.v[j]}</b>`]};}]});

topic('e2-sort2',{b:5,s:28,title:'Sorting two ways',area:'D',dfe:'24',vq:'sorting by two criteria carroll diagram',
 lesson:{idea:'Sometimes things are sorted by two rules at once, like colour and size.',steps:['Check the first rule: is it the right colour?','Then check the second rule: is it the right size?','Only count things that fit both rules.'],ex:{q:'Helmets: red large, red small, blue large, red large. How many are red and large?',w:['Go through one at a time.','Red large: yes. Red small: no. Blue large: no. Red large: yes.','2 are red and large.']},trap:'"Red and large" needs both. A red small helmet does not count.'},
 gens:[()=>{const C=['red','blue'],Z=['large','small'],items=[...Array(rnd(6,8))].map(()=>[pick(C),pick(Z)]),c=pick(C),z=pick(Z),n=items.filter(x=>x[0]===c&&x[1]===z).length;return{text:`Here is a list of helmets:${tbl(['Helmet','Colour','Size'],items.map((x,i)=>[i+1,cap(x[0]),cap(x[1])]))}How many helmets are ${c} <b>and</b> ${z}?`,ans:n,steps:[`Check each row for both ${c} and ${z}.`,`Rows that fit: ${items.map((x,i)=>x[0]===c&&x[1]===z?i+1:0).filter(Boolean).join(', ')||'none'}. That is <b>${n}</b>.`]};},
  ()=>{const v=[rnd(1,9),rnd(1,9),rnd(1,9),rnd(1,9)],i=rnd(0,3),lab=[['metal','long'],['metal','short'],['wood','long'],['wood','short']][i];return{text:`Poles in the store are sorted two ways.${tbl(['','Long','Short'],[['Metal',v[0],v[1]],['Wood',v[2],v[3]]])}How many poles are ${lab[0]} and ${lab[1]}?`,ans:v[i],steps:[`Find the ${cap(lab[0])} row and the ${cap(lab[1])} column.`,`Where they meet: <b>${v[i]}</b>.`]};}]});

topic('e2-format',{b:5,s:29,title:'Showing information another way',area:'D',dfe:'25',vq:'drawing bar charts from a table',
 lesson:{idea:'The same information can be shown as a list, a table or a bar chart. To change from one to another, copy each number carefully.',steps:['Count or read the number for each group.','Put the groups along the bottom of the chart.','Draw each bar up to its number.','Check the chart against the table.'],ex:{q:'A table says Tea 6, Coffee 4. How tall should the Coffee bar be?',w:['Find Coffee in the table: 4.','The Coffee bar goes up to 4.']},trap:'Check every bar against the table before you finish.'},
 gens:[()=>{const c=pickN(['Tea','Coffee','Juice','Water','Milk'],3),v=pickN([2,3,4,5,6,7,8],3),alt=[v.slice().reverse(),[v[1],v[0],v[2]],[v[0],v[2],v[1]]].filter(a=>a.join()!==v.join()),o=shuffle([v,alt[0],alt[1]]);return{text:`This table shows the drinks people chose.${tbl(['Drink','Number'],c.map((x,i)=>[x,v[i]]))}Which bar chart shows the same information?`,kind:'choice',opts:o.map(a=>figBars(c,a,{max:8,every:2})),ans:o.indexOf(v),steps:[`Check each bar: ${c.map((x,i)=>`${x} ${v[i]}`).join(', ')}.`,'Only one chart has all three bars at the right height.']};},
  ()=>{const c=pickN(['Robin','Blackbird','Gull','Magpie','Wren'],3),v=c.map(()=>rnd(2,14)),i=rnd(0,2);return{text:`A bird count is recorded as a tally.${tbl(['Bird','Tally'],c.map((x,k)=>[x,tally(v[k])]))}In a bar chart of this information, what number should the ${c[i]} bar go up to?`,ans:v[i],steps:[`Count the ${c[i]} tally in fives.`,`The bar goes up to <b>${v[i]}</b>.`]};},
  ()=>{const C=['red','blue','green'],list=[...Array(rnd(8,11))].map(()=>pick(C)),c=pick(C),n=list.filter(x=>x===c).length;return{text:`The colours of cars passing the gate were:<br><b>${list.join(', ')}</b><br>You are making a table. What number goes next to "${c}"?`,ans:n,steps:[`Count every "${c}" in the list.`,`There ${n===1?'is':'are'} <b>${n}</b>.`]};}]});

